package com.arjunren.hospital.config;
import com.arjunren.hospital.domain.Role;import com.arjunren.hospital.entity.*;import com.arjunren.hospital.repository.*;import java.time.LocalDate;import org.springframework.boot.CommandLineRunner;import org.springframework.context.annotation.Profile;import org.springframework.security.crypto.password.PasswordEncoder;import org.springframework.stereotype.Component;
@Component@Profile("dev")public class DevDataSeeder implements CommandLineRunner{private final UserRepository users;private final DoctorRepository doctors;private final PatientRepository patients;private final PasswordEncoder encoder;public DevDataSeeder(UserRepository u,DoctorRepository d,PatientRepository p,PasswordEncoder e){users=u;doctors=d;patients=p;encoder=e;}public void run(String...args){seed("admin@example.com","Development Admin","AdminPassword123!",Role.ADMIN);seed("reception@example.com","Development Receptionist","ReceptionPassword123!",Role.RECEPTIONIST);var d=seed("doctor@example.com","Dr. Development","DoctorPassword123!",Role.DOCTOR);var p=seed("patient@example.com","Development Patient","PatientPassword123!",Role.PATIENT);if(doctors.findByUserId(d.getId()).isEmpty())doctors.save(new DoctorProfile(d,"DEV-001","General Medicine",30));if(patients.findByUserId(p.getId()).isEmpty())patients.save(new PatientProfile(p,"MRN-001",LocalDate.of(1990,1,1),"555-0100"));}private AppUser seed(String e,String n,String p,Role r){return users.findByEmailIgnoreCase(e).orElseGet(()->users.save(new AppUser(e,encoder.encode(p),n,r)));}}

